/* Licensed Japanese coastal photographs. Controls remain available without motion. */
(()=>{'use strict';const $=id=>document.getElementById(id),frame=document.querySelector('.home-coast-frame');if(!frame)return;const motion=matchMedia('(prefers-reduced-motion: reduce)'),tr=(en,ar=en,ja=en)=>PortalLanguage.current==='ar'?ar:PortalLanguage.current==='ja'?ja:en,habitats={reef:['Coral reefs','شعاب مرجانية','サンゴ礁'],mangrove:['Mangrove forest','غابات المنغروف','マングローブ林'],rocky:['Rocky shore','ساحل صخري','岩礁海岸'],coast:['Coast','ساحل','海岸'],beach:['Sandy shore','ساحل رملي','砂浜']};let slides=[],index=0,wanted=0,active=0,request=0,timer,paused=motion.matches,hovered=false,focused=false,visible=true;
function caption(){if(!slides.length)return;const s=slides[index],lang=PortalLanguage.current,place=s.place[lang]||s.place.en,kind=tr(...habitats[s.habitat]);$('coastCaption').replaceChildren();const title=document.createElement('strong');title.textContent=place+' · '+kind;const credit=document.createElement('span'),author=document.createElement('a'),license=document.createElement('a');author.href=s.source;author.textContent=s.author;license.href=s.licenseUrl;license.textContent=s.license;for(const a of [author,license]){a.target='_blank';a.rel='noopener';}credit.append(author,' · ',license,' · '+tr('cropped for display','اقتُطعت للعرض','表示用にトリミング'));$('coastCaption').append(title,credit);$('coastCount').textContent=`${index+1} / ${slides.length}`;for(const image of frame.querySelectorAll('.is-active'))image.alt=place+' · '+kind;}
function labels(){frame.setAttribute('aria-roledescription',tr('slideshow','عرض صور','スライドショー'));$('coastTag').textContent=tr('Japan · Coastal habitats','اليابان · الموائل الساحلية','日本・沿岸の生態系');frame.setAttribute('aria-label',tr('Japanese coastal habitats','الموائل الساحلية اليابانية','日本の沿岸生態系'));$('coastPrevious').setAttribute('aria-label',tr('Previous photograph','الصورة السابقة','前の写真'));$('coastNext').setAttribute('aria-label',tr('Next photograph','الصورة التالية','次の写真'));$('coastPause').textContent=paused?'▶':'Ⅱ';$('coastPause').setAttribute('aria-label',paused?tr('Play slideshow','تشغيل عرض الصور','スライドショーを再生'):tr('Pause slideshow','إيقاف عرض الصور مؤقتاً','スライドショーを停止'));$('coastPause').setAttribute('aria-pressed',String(paused));caption();}
function schedule(){clearInterval(timer);if(!paused&&!hovered&&!focused&&visible&&!document.hidden&&slides.length>1)timer=setInterval(()=>show(wanted+1),6500);}
async function show(next,manual=false){if(!slides.length)return;const token=++request;wanted=(next+slides.length)%slides.length;const target=wanted,back=active?$('coastImageA'):$('coastImageB'),front=active?$('coastImageB'):$('coastImageA');back.src=slides[target].image;try{await back.decode();}catch{if(token===request){$('coastCount').textContent=tr('Photo unavailable','الصورة غير متاحة','写真を読み込めません');}return;}if(token!==request)return;back.classList.add('is-active');back.setAttribute('aria-hidden','false');front.classList.remove('is-active');front.setAttribute('aria-hidden','true');active=active?0:1;index=target;$('coastCaption').setAttribute('aria-live',manual?'polite':'off');caption();const preload=new Image();preload.src=slides[(index+1)%slides.length].image;if(manual)schedule();}
$('coastPrevious').onclick=()=>show(wanted-1,true);$('coastNext').onclick=()=>show(wanted+1,true);$('coastPause').onclick=()=>{paused=!paused;if(!paused){focused=false;hovered=false;}labels();schedule();};frame.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(wanted+(e.key==='ArrowRight'?1:-1),true);}};frame.onmouseenter=()=>{hovered=true;schedule();};frame.onmouseleave=()=>{hovered=false;schedule();};frame.addEventListener('focusin',()=>{focused=true;schedule();});frame.addEventListener('focusout',e=>{if(!frame.contains(e.relatedTarget)){focused=false;schedule();}});document.addEventListener('visibilitychange',schedule);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;schedule();},{threshold:.25}).observe(frame);window.addEventListener('portallanguagechange',labels);motion.addEventListener('change',()=>{if(motion.matches)paused=true;labels();schedule();});
fetch('content/home-coasts.json?v=20261102-japan-r1').then(r=>{if(!r.ok)throw Error('Coastal photo catalogue unavailable');return r.json();}).then(data=>{slides=data.slides;labels();schedule();const next=new Image();next.src=slides[1].image;document.documentElement.dataset.galleryReady='true';}).catch(()=>{paused=true;labels();});})();
